import { type Book } from '../types/book';

export function BookCard({ book }: { book: Book }): JSX.Element {
  return <article className="card">{book.title}</article>;
}

export function Drawer(): JSX.Element {
  return <aside className="drawer">Drawer content</aside>;
}

import { render, screen } from '@testing-library/react';
import { BookCard } from './BookCard';

test('renders title', () => {
  render(<BookCard book={{ id: '1', title: 'Test', author: 'A', status: 'to-read' }} />);
  expect(screen.getByText('Test')).toBeInTheDocument();
});

